mapper.select:
SELECT , LEAST(1.0, CASE WHEN POSITION(#{query} IN LOWER(c.file_path))>0 THEN .75 ELSE 0 END +CASE WHEN POSITION(#{query} IN LOWER(COALESCE(c.symbol_name,'')))>0 THEN .95 ELSE 0 END +CASE WHEN POSITION(#{query} IN LOWER(c.content))>0 THEN .65 ELSE 0 END +(
CASE WHEN LOWER(COALESCE(c.symbol_name,''))=#{term} THEN .85 WHEN POSITION(#{term} IN LOWER(COALESCE(c.symbol_name,'')))>0 THEN .65 WHEN POSITION(#{term} IN LOWER(c.file_path))>0 THEN .5 WHEN POSITION(#{term} IN LOWER(c.content))>0 THEN .3 ELSE 0 END
) / #{termCount} ) lexical_score,0.0 semantic_score FROM code_chunks c WHERE c.repo_id=#{repositoryId} AND c.snapshot_id=(SELECT current_snapshot_id FROM repositories WHERE id=#{repositoryId}) AND( POSITION(#{query} IN LOWER(c.file_path))>0 OR POSITION(#{query} IN LOWER(COALESCE(c.symbol_name,'')))>0 OR POSITION(#{query} IN LOWER(c.content))>0
OR POSITION(#{term} IN LOWER(c.file_path))>0 OR POSITION(#{term} IN LOWER(COALESCE(c.symbol_name,'')))>0 OR POSITION(#{term} IN LOWER(c.content))>0
) ORDER BY lexical_score DESC,c.file_path,c.start_line NULLS FIRST LIMIT #{limit}

SELECT ,0.0 lexical_score,
GREATEST(0.0,1-(e.embedding <=> CAST(#{vector} AS vector))) semantic_score
FROM chunk_embeddings e JOIN code_chunks c ON c.id=e.chunk_id
WHERE c.repo_id=#{repositoryId}
AND c.snapshot_id=(SELECT current_snapshot_id FROM repositories WHERE id=#{repositoryId})
AND e.model=#{model} AND e.dimension=#{dimension}
AND e.content_hash=c.content_hash
ORDER BY e.embedding <=> CAST(#{vector} AS vector),c.file_path,c.start_line NULLS FIRST
LIMIT #{limit}

SELECT , LEAST(1.0, CASE WHEN POSITION(#{query} IN LOWER(c.title))>0 THEN .95 ELSE 0 END +CASE WHEN POSITION(#{query} IN LOWER(c.content))>0 THEN .65 ELSE 0 END +CASE WHEN POSITION(#{query} IN LOWER(ARRAY_TO_STRING(c.tags,' ')))>0 THEN .8 ELSE 0 END +(
CASE WHEN POSITION(#{term} IN LOWER(c.title))>0 THEN .7 WHEN POSITION(#{term} IN LOWER(ARRAY_TO_STRING(c.tags,' ')))>0 THEN .6 WHEN POSITION(#{term} IN LOWER(c.content))>0 THEN .35 ELSE 0 END
) / #{termCount} ) lexical_score,0.0 semantic_score FROM knowledge_cards c WHERE AND( POSITION(#{query} IN LOWER(c.title))>0 OR POSITION(#{query} IN LOWER(c.content))>0 OR POSITION(#{query} IN LOWER(ARRAY_TO_STRING(c.tags,' ')))>0
OR POSITION(#{term} IN LOWER(c.title))>0 OR POSITION(#{term} IN LOWER(c.content))>0 OR POSITION(#{term} IN LOWER(ARRAY_TO_STRING(c.tags,' ')))>0
) ORDER BY lexical_score DESC,c.updated_at DESC LIMIT #{limit}

SELECT id FROM qa_conversations
WHERE thread_id=#{threadId}
ORDER BY turn_no LIMIT 1 FOR UPDATE

mapper.insert:
INSERT INTO knowledge_cards(
    id,repo_id,title,card_type,content,tags,knowledge_kind,severity,enforcement,
    owner_account_id,scope_payload,obligations_payload,publication_status,review_status,
    created_by,updated_by
) VALUES(
    #{id},#{repositoryId},#{title},#{cardType},#{content},
    #{tags,typeHandler=org.apache.ibatis.type.ArrayTypeHandler},#{knowledgeKind},#{severity},
    #{enforcement},#{ownerAccountId},CAST(#{scopePayload} AS jsonb),
    CAST(#{obligationsPayload} AS jsonb),'DRAFT','UNREVIEWED',#{actorId},#{actorId}
)

mapper.update:
UPDATE knowledge_cards SET review_status=#{reviewStatus},reviewed_by=#{actorId},
    reviewed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP
WHERE id=#{id} AND repo_id=#{repositoryId}

UPDATE knowledge_cards SET publication_status=#{publicationStatus},updated_by=#{actorId},
    updated_at=CURRENT_TIMESTAMP
WHERE id=#{id} AND repo_id=#{repositoryId}

mapper.select:
SELECT id,snapshot_id,file_path,symbol_name,start_line,end_line,content,content_hash
FROM code_chunks WHERE repo_id=#{repositoryId} AND id=#{chunkId}
AND snapshot_id=(SELECT current_snapshot_id FROM repositories WHERE id=#{repositoryId})

SELECT c.id,c.content,c.content_hash FROM code_chunks c
LEFT JOIN chunk_embeddings e ON e.chunk_id=c.id
WHERE c.repo_id=#{repositoryId}
AND c.snapshot_id=(SELECT current_snapshot_id FROM repositories WHERE id=#{repositoryId})
AND(e.chunk_id IS NULL OR e.content_hash<>c.content_hash OR e.model<>#{model}
OR e.dimension<>#{dimension} OR e.retrieval_capability<>#{capability})
